SELECT gap_bucket, COUNT(*) AS n FROM (SELECT CASE WHEN g < 2.5 THEN 'a<=2.5s' WHEN g < 5 THEN 'b2.5-5s' WHEN g < 10 THEN 'c5-10s' ELSE 'd>=10s' END AS gap_bucket FROM (SELECT TIMESTAMPDIFF(MICROSECOND, LAG(observed_at) OVER (ORDER BY observed_at), observed_at)/1e6 AS g FROM market_price_event WHERE symbol = 'EGLDUSDT' AND observed_at BETWEEN '2026-10-11 22:40:00' AND '2026-10-11 22:43:40') x WHERE g IS NOT NULL) y GROUP BY gap_bucket ORDER BY gap_bucket